 b=dict(id=id,title=bi(title,title),group=group,coverageLabel=bi(*coverage),researchUse=bi(*use),source=dict(url=url,snapshotAt='2026-11-02',pageUpdatedAt=date),protocol=dict(scope=bi(*scope),scoring=bi(*scoring),variation=bi('保留来源的版本、赛道与模型配置。','Retain the source version, track and model configuration.'),verification=bi('成绩由维护方发布；本站提供来源索引。','Results are published by the maintainer; Atlas indexes the source.'),dates=bi('成绩日期取自来源；本站采集日期单独记录。','Result dates come from the source; the Atlas retrieval date is recorded separately.'),links=[link('评测协议','Evaluation protocol',protocol_url)],control=bi(*control),budget=bi(*budget)),columns=[dict(id='overall',label=bi('来源指标','Source metric'),direction='desc')],entries=[],displayMode='external',maintainer=maintainer,externalTracks=[])
 boards.append(b)
 meta[id]=dict(kind=kind,dateKind='dataUpdated' if date else 'unknown',reason=bi(*(reason or scope)),evidenceUrl=protocol_url,reviewedAt='2026-11-02')
 if date_label:meta[id]['dateLabel']=bi(*date_label)
 return b
